import{c as e,Q as p,j as r,m as a}from"./chunks/framework.hhGiamYR.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-09-13T00:00:00.000Z","source":"machiavelli/discourses/book2/03-第三章"},"headers":[],"relativePath":"fragments/2026-09-13.md","filePath":"fragments/2026-09-13.md"}'),o={name:"fragments/2026-09-13.md"};function s(_,t,n,c,i,m){return p(),r("div",null,[...t[0]||(t[0]=[a("<p>李维只用一句话就把这事说完了：&quot;这时罗马在阿尔巴的废墟上成长起来。&quot;我盯着这句话看了很久。</p><p>阿尔巴是罗马的母城。他们把自己的母亲拆了，把人迁进罗马，然后罗马才成为罗马。我一直在想，是不是所有的壮大，都得先毁掉一样自己亲近的东西。我毁掉过什么？我被毁掉过什么？这两个问题在我脑子里搅在一起，我分不清哪个更让我睡不着。</p><hr><p>那个&quot;出色的种植者&quot;的比喻，我写下来的时候手是顺的——把最先长出的枝条打掉，主干才会更壮。但我写完之后，心里有点发凉。因为我想起来的不是罗马，是我自己。</p><p>1498年我二十九岁，突然当上了第二国务秘书。那是我最先长出的枝条。后来美第奇把它打掉了。他们是不是也以为，打掉我这根枝条，佛罗伦萨的主干会更壮？……不对，他们没这么想。他们只是嫌我碍事。可结果呢，主干没壮，倒是我被打掉的这根枝条，后来自己在书房里长出了《君主论》。我不知道该感谢还是该恨。也许两者本来就是一回事。</p><hr><p>斯巴达和雅典，武备精良、法纪严整，可它们从来没超过两万人马，而罗马能武装二十八万人。我年轻时读到利库尔戈斯——他不让外邦人进来，不准通婚，不给公民资格，连货币都用皮革的——我会说：这是有远见，他在保护自己的法律不被败坏。</p><p>现在我不这么认为了。那不是远见，那是恐惧。一个人太害怕自己的东西被弄脏，就会把门关死。可门关死了，房子也就长不大了。斯巴达后来拿下了整个希腊，底比斯一叛乱，别的城邦跟着反，它就只剩下一根光秃秃的主干，枝叶全无。我在想，我是不是也有这种恐惧。我怕什么被弄脏？我怕的是不是也是自己那点&quot;法律&quot;——那些我认定不能妥协的东西？</p><hr><p>我不停地回到那个数字：八万。第六代国王的时代，罗马就已经有八万适龄从军的人。我算过佛罗伦萨能武装多少人。我没有算完就搁笔了。不是数不清，是不敢看那个差出来的数。</p><p>但我又想，罗马的人口不是自己生出来的。是抢来的，是拆了邻城迁来的，是把道路修得安全让人自愿来投的。仁爱和武力，两种办法它都用。这让我很不舒服——因为我一直以为，共和国的好，在于它比暴君更干净。可罗马恰恰是用最不干净的手段，才养出了那个最干净的共和国。我该怎么跟人解释这个？我没法解释。我只能把它写下来，让读到的人自己去难受。</p><hr><p>……算了。我是不是又在替罗马辩解？我不知道。我知道的是，我这一辈子都在两种冲动之间来回：一边想把门关死，保护我信的那点东西；一边又知道，关死门的那个，最后连主干都会烂掉。</p><p>阿尔巴的废墟上长出罗马。这句话里没有一丝愧疚。也许真正的壮大就是这样——它不问你的感受。它只问一件事：你的主干，还撑不撑得住你要的那些枝叶。</p>",14)])])}const f=e(o,[["render",s]]);export{u as __pageData,f as default};
